messages.content:
Siap! 🚀 Bunga Neon: Pertahanan Kapten Raka segera dibangun — pasang menara bagian bunga yang tepat untuk menghalau bug digital dan selamatkan bunga raksasa.

```html
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
<title>Bunga Neon: Pertahanan Kapten Raka</title>
<script type="application/json" id="aisys-story">
{
  "title": "Bunga Neon: Pertahanan Kapten Raka",
  "hero": { "name": "Kapten Raka", "emoji": "🧑‍🚀", "desc": "Siswa SMA jenius dengan drone pintar penjaga Kota Neon" },
  "world": { "name": "Kota Neon", "emoji": "🌆" },
  "mood": { "from": "#0f172a", "to": "#1e3a8a" },
  "prolog": [
    { "text": "Di Kota Neon yang berkilau, Kapten Raka dan drone pintarnya menjaga bunga raksasa di tengah kota.", "emoji": "🌸" },
    { "text": "Gerombolan bug digital menyerbu! Ternyata mereka dulu serangga penyerbuk yang tersesat.", "emoji": "🐛" },
    { "text": "Pasang menara bagian bunga yang tepat untuk menghalau mereka dan menyelamatkan bunga.", "emoji": "🎯" }
  ],
  "goal": { "text": "Halau 10 bug dengan menara yang tepat untuk menyelamatkan bunga raksasa" },
  "ending": {
    "menang": { "text": "Bug kembali menjadi serangga penyerbuk dan bunga raksasa mekar megah! Kota Neon bersinar berkat Kapten Raka.", "emoji": "🏆" },
    "kalah": { "text": "Bunga layu untuk sementara, tapi Kapten Raka bangkit menyusun strategi baru. Ayo coba lagi!", "emoji": "💫" }
  }
}
</script>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #0a0f1e; font-family: 'Segoe UI', system-ui, sans-serif; }
  #wrap { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; }
  canvas { display: block; touch-action: none; }
  #muteBtn { position: fixed; top: 10px; right: 10px; z-index: 20; background: rgba(30,58,138,0.7); color: #e0f2fe; border: 1px solid rgba(125,211,252,0.5); border-radius: 8px; padding: 6px 12px; font-size: 14px; cursor: pointer; }
</style>
</head>
<body>
<div id="wrap"><canvas id="cv"></canvas></div>
<button id="muteBtn">🔊</button>
<script>
(function(){
  "use strict";
  const W = 960, H = 540;
  const cv = document.getElementById('cv');
  const ctx = cv.getContext('2d');
  let scale = 1, offX = 0, offY = 0;

  function resize(){
    const vw = window.innerWidth, vh = window.innerHeight;
    scale = Math.min(vw / W, vh / H);
    const cw = Math.floor(W * scale), ch = Math.floor(H * scale);
    cv.width = cw; cv.height = ch;
    cv.style.width = cw + 'px'; cv.style.height = ch + 'px';
    offX = 0; offY = 0;
  }
  window.addEventListener('resize', resize);
  resize();

  function toLogical(clientX, clientY){
    const r = cv.getBoundingClientRect();
    return { x: (clientX - r.left) / scale, y: (clientY - r.top) / scale };
  }

  // ---------- AUDIO ----------
  let audioCtx = null, muted = false;
  function unlockAudio(){
    if (!audioCtx){
      try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){}
    }
    if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
  }
  function beep(freq, dur, type, vol){
    if (muted || !audioCtx) return;
    const o = audioCtx.createOscillator();
    const g = audioCtx.createGain();
    o.type = type || 'sine';
    o.frequency.value = freq;
    g.gain.value = vol || 0.08;
    o.connect(g); g.connect(audioCtx.destination);
    const t = audioCtx.currentTime;
    g.gain.setValueAtTime(g.gain.value, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.start(t); o.stop(t + dur);
  }
  const sfx = {
    correct: () => { beep(660, 0.12, 'sine', 0.1); setTimeout(()=>beep(880,0.15,'sine',0.1), 90); },
    wrong: () => { beep(200, 0.25, 'sawtooth', 0.08); },
    place: () => { beep(440, 0.08, 'triangle', 0.07); },
    shoot: () => { beep(520, 0.05, 'square', 0.03); },
    lose: () => { beep(160, 0.4, 'sawtooth', 0.1); },
    win: () => { [523,659,784,1047].forEach((f,i)=>setTimeout(()=>beep(f,0.2,'sine',0.1), i*120)); }
  };
  document.getElementById('muteBtn').addEventListener('click', (e)=>{
    e.stopPropagation();
    muted = !muted;
    document.getElementById('muteBtn').textContent = muted ? '🔇' : '🔊';
  });

  // ---------- MATERI ----------
  const CATEGORIES = [
    { id: 'putik', label: 'Putik', color: '#e879f9', desc: 'Organ kelamin betina' },
    { id: 'benangsari', label: 'Benang Sari', color: '#fbbf24', desc: 'Organ kelamin jantan' },
    { id: 'mahkota', label: 'Mahkota', color: '#fb7185', desc: 'Menarik penyerbuk' }
  ];
  const BANK = [
    { text: 'Kepala putik lengket', cat: 'putik', exp: 'Bagian putik yang menangkap serbuk sari.' },
    { text: 'Bakal buah', cat: 'putik', exp: 'Bagian putik yang berkembang jadi buah.' },
    { text: 'Tangkai putik', cat: 'putik', exp: 'Penghubung kepala putik ke bakal buah.' },
    { text: 'Serbuk sari', cat: 'benangsari', exp: 'Sel kelamin jantan yang dihasilkan benang sari.' },
    { text: 'Tangkai sari', cat: 'benangsari', exp: 'Penopang kepala sari pada benang sari.' },
    { text: 'Kepala sari', cat: 'benangsari', exp: 'Tempat serbuk sari diproduksi.' },
    { text: 'Kelopak berwarna', cat: 'mahkota', exp: 'Warna menarik perhatian serangga penyerbuk.' },
    { text: 'Aroma bunga', cat: 'mahkota', exp: 'Aroma memikat serangga untuk datang.' },
    { text: 'Nektar manis', cat: 'mahkota', exp: 'Cairan manis sebagai hadiah bagi penyerbuk.' }
  ];

  // ---------- GAME STATE ----------
  const PATH = [
    { x: -40, y: 120 }, { x: 200, y: 120 }, { x: 200, y: 300 },
    { x: 520, y: 300 }, { x: 520, y: 130 }, { x: 800, y: 130 },
    { x: 800, y: 420 }, { x: 480, y: 420 }, { x: 480, y: 470 }
  ];
  const FLOWER = { x: 480, y: 470 };

  // Slot menara: di samping jalur, dalam jangkauan
  const SLOTS = [
    { x: 120, y: 210 }, { x: 300, y: 210 }, { x: 300, y: 390 },
    { x: 420, y: 210 }, { x: 620, y: 220 }, { x: 620, y: 360 },
    { x: 700, y: 220 }, { x: 700, y: 360 }, { x: 380, y: 360 }
  ];
  const TOWER_RANGE = 130;

  let state = 'start'; // start, playing, win, lose
  let lives = 5;
  let correctCount = 0;
  const TARGET = 10;
  let towers = []; // {slotIndex, cat}
  let enemies = [];
  let particles = [];
  let projectiles = [];
  let spawnTimer = 0;
  let spawnInterval = 2.2;
  let selectedSlot = -1;
  let feedback = { text: '', timer: 0, color: '#fff' };
  let lastTime = 0;
  let enemyIdCounter = 0;
  let bankQueue = [];

  function shuffle(a){ for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; } return a; }
  function refillQueue(){ bankQueue = shuffle(BANK.slice()); }
  refillQueue();

  function resetGame(){
    lives = 5; correctCount = 0; towers = []; enemies = []; particles = [];
    projectiles = []; spawnTimer = 0; spawnInterval = 2.2; selectedSlot = -1;
    feedback = { text: '', timer: 0, color: '#fff' };
    refillQueue();
  }

  // ---------- PATH HELPERS ----------
  function pathLength(){
    let len = 0;
    for (let i=1;i<PATH.length;i++){
      len += Math.hypot(PATH[i].x-PATH[i-1].x, PATH[i].y-PATH[i-1].y);
    }
    return len;
  }
  const TOTAL_LEN = pathLength();
  function pointAt(dist){
    let d = dist;
    for (let i=1;i<PATH.length;i++){
      const seg = Math.hypot(PATH[i].x-PATH[i-1].x, PATH[i].y-PATH[i-1].y);
      if (d <= seg){
        const t = d / seg;
        return { x: PATH[i-1].x + (PATH[i].x-PATH[i-1].x)*t, y: PATH[i-1].y + (PATH[i].y-PATH[i-1].y)*t };
      }
      d -= seg;
    }
    return { x: PATH[PATH.length-1].x, y: PATH[PATH.length-1].y };
  }

  // ---------- ENEMY SPAWN ----------
  function spawnEnemy(){
    if (bankQueue.length === 0) refillQueue();
    const item = bankQueue.pop();
    enemies.push({
      id: ++enemyIdCounter,
      item: item,
      dist: 0,
      speed: 42,
      hp: 1,
      judged: false,
      wobble: Math.random()*Math.PI*2
    });
  }

  // ---------- TOWER LOGIC ----------
  function towerAt(slotIndex){
    return towers.find(t => t.slotIndex === slotIndex);
  }

  function updateTowers(dt){
    for (const t of towers){
      const slot = SLOTS[t.slotIndex];
      t.cool = (t.cool || 0) - dt;
      if (t.cool > 0) continue;
      // cari musuh terdekat dalam jangkauan yang cocok
      let target = null, bestDist = Infinity;
      for (const e of enemies){
        if (e.judged) continue;
        if (e.item.cat !== t.cat) continue;
        const p = pointAt(e.dist);
        const d = Math.hypot(p.x - slot.x, p.y - slot.y);
        if (d < TOWER_RANGE && d < bestDist){ bestDist = d; target = e; }
      }
      if (target){
        t.cool = 0.7;
        const p = pointAt(target.dist);
        projectiles.push({ x: slot.x, y: slot.y, tx: p.x, ty: p.y, targetId: target.id, color: CATEGORIES.find(c=>c.id===t.cat).color, life: 0.4 });
        sfx.shoot();
      }
    }
  }

  function updateProjectiles(dt){
    for (let i=projectiles.length-1;i>=0;i--){
      const pr = projectiles[i];
      pr.life -= dt;
      if (pr.life <= 0){
        // hit target
        const e = enemies.find(en => en.id === pr.targetId && !en.judged);
        if (e){
          e.judged = true;
          e.hp = 0;
          correctCount++;
          sfx.correct();
          feedback = { text: 'Benar! ' + e.item.exp, timer: 2, color: '#4ade80' };
          for (let k=0;k<8;k++){
            particles.push({ x: pr.tx, y: pr.ty, vx: (Math.random()-0.5)*120, vy: (Math.random()-0.5)*120, life: 0.6, color: pr.color });
          }
        }
        projectiles.splice(i,1);
      }
    }
  }

  function updateEnemies(dt){
    for (let i=enemies.length-1;i>=0;i--){
      const e = enemies[i];
      if (e.judged){
        e.dist += 200 * dt; // kabur cepat
        if (e.dist > TOTAL_LEN + 60) enemies.splice(i,1);
        continue;
      }
      e.dist += e.speed * dt;
      e.wobble += dt * 6;
      if (e.dist >= TOTAL_LEN){
        // sampai bunga = kalah nyawa
        lives--;
        sfx.lose();
        feedback = { text: 'Bug lolos! ' + e.item.text + ' = ' + labelOf(e.item.cat), timer: 2, color: '#f87171' };
        enemies.splice(i,1);
        if (lives <= 0){ endGame('lose'); return; }
      }
    }
  }

  function labelOf(catId){
    const c = CATEGORIES.find(x=>x.id===catId);
    return c ? c.label : catId;
  }

  function updateParticles(dt){
    for (let i=particles.length-1;i>=0;i--){
      const p = particles[i];
      p.x += p.vx * dt; p.y += p.vy * dt;
      p.life -= dt;
      if (p.life <= 0) particles.splice(i,1);
    }
  }

  function endGame(result){
    state = result;
    if (result === 'win'){ sfx.win(); if (window.AISYS && AISYS.end) AISYS.end('menang'); }
    else { sfx.lose(); if (window.AISYS && AISYS.end) AISYS.end('kalah'); }
  }

  // ---------- UPDATE ----------
  function update(dt){
    if (state !== 'playing') return;
    if (feedback.timer > 0) feedback.timer -= dt;

    spawnTimer -= dt;
    if (spawnTimer <= 0){
      spawnEnemy();
      spawnTimer = spawnInterval;
      spawnInterval = Math.max(1.2, spawnInterval - 0.05);
    }
    updateEnemies(dt);
    updateTowers(dt);
    updateProjectiles(dt);
    updateParticles(dt);

    if (correctCount >= TARGET && state === 'playing') endGame('win');
  }

  // ---------- DRAW ----------
  function roundRect(x,y,w,h,r){
    ctx.beginPath();
    ctx.moveTo(x+r,y);
    ctx.arcTo(x+w,y,x+w,y+h,r);
    ctx.arcTo(x+w,y+h,x,y+h,r);
    ctx.arcTo(x,y+h,x,y,r);
    ctx.arcTo(x,y,x+w,y,r);
    ctx.closePath();
  }

  function drawBackground(){
    const g = ctx.createLinearGradient(0,0,0,H);
    g.addColorStop(0, '#0f172a');
    g.addColorStop(0.5, '#1e293b');
    g.addColorStop(1, '#1e3a8a');
    ctx.fillStyle = g;
    ctx.fillRect(0,0,W,H);

    // gedung neon
    for (let i=0;i<14;i++){
      const bx = (i*72 + 20) % W;
      const bh = 120 + ((i*53)%180);
      const by = H - bh - 60;
      const bg = ctx.createLinearGradient(bx, by, bx, by+bh);
      bg.addColorStop(0, 'rgba(56,189,248,0.15)');
      bg.addColorStop(1, 'rgba(30,58,138,0.35)');
      ctx.fillStyle = bg;
      roundRect(bx, by, 52, bh, 6);
      ctx.fill();
      // jendela
      ctx.fillStyle = 'rgba(125,211,252,0.5)';
      for (let wy=by+12; wy<by+bh-10; wy+=22){
        for (let wx=bx+8; wx<bx+46; wx+=16){
          if ((wx+wy+i)%3 !== 0) ctx.fillRect(wx, wy, 8, 10);
        }
      }
    }
  }

  function drawPath(){
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    ctx.strokeStyle = 'rgba(56,189,248,0.15)';
    ctx.lineWidth = 46;
    ctx.beginPath();
    ctx.moveTo(PATH[0].x, PATH[0].y);
    for (let i=1;i<PATH.length;i++) ctx.lineTo(PATH[i].x, PATH[i].y);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(125,211,252,0.35)';
    ctx.lineWidth = 3;
    ctx.setLineDash([12,10]);
    ctx.beginPath();
    ctx.moveTo(PATH[0].x, PATH[0].y);
    for (let i=1;i<PATH.length;i++) ctx.lineTo(PATH[i].x, PATH[i].y);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  function drawFlower(){
    const t = performance.now()/1000;
    const pulse = 1 + Math.sin(t*2)*0.04;
    ctx.save();
    ctx.translate(FLOWER.x, FLOWER.y);
    ctx.scale(pulse, pulse);
    // glow
    ctx.shadowColor = '#f472b6'; ctx.shadowBlur = 30;
    // kelopak
    for (let i=0;i<8;i++){
      const a = (i/8)*Math.PI*2 + t*0.3;
      ctx.fillStyle = i%2===0 ? '#fb7185' : '#f472b6';
      ctx.beginPath();
      ctx.ellipse(Math.cos(a)*22, Math.sin(a)*22, 16, 10, a, 0, Math.PI*2);
      ctx.fill();
    }
    ctx.shadowBlur = 0;
    // pusat
    const cg = ctx.createRadialGradient(0,0,2,0,0,16);
    cg.addColorStop(0,'#fef08a'); cg.addColorStop(1,'#fbbf24');
    ctx.fillStyle = cg;
    ctx.beginPath(); ctx.arc(0,0,14,0,Math.PI*2); ctx.fill();
    ctx.restore();
  }

  function drawSlots(){
    for (let i=0;i<SLOTS.length;i++){
      const s = SLOTS[i];
      const tw = towerAt(i);
      const sel = selectedSlot === i;
      ctx.save();
      if (tw){
        const cat = CATEGORIES.find(c=>c.id===tw.cat);
        ctx.shadowColor = cat.color; ctx.shadowBlur = 16;
        const g = ctx.createLinearGradient(s.x-18, s.y-18, s.x+18, s.y+18);
        g.addColorStop(0, cat.color); g.addColorStop(1, '#1e293b');
        ctx.fillStyle = g;
        roundRect(s.x-18, s.y-18, 36, 36, 8); ctx.fill();
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(cat.label.split(' ')[0], s.x, s.y);
      } else {
        ctx.strokeStyle = sel ? '#7dd3fc' : 'rgba(125,211,252,0.5)';
        ctx.lineWidth = sel ? 3 : 2;
        ctx.setLineDash([5,4]);
        roundRect(s.x-16, s.y-16, 32, 32, 8); ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = 'rgba(125,211,252,0.6)';
        ctx.font = 'bold 18px sans-serif';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText('+', s.x, s.y);
      }
      ctx.restore();
    }
  }

  function drawEnemies(){
    for (const e of enemies){
      const p = pointAt(e.dist);
      const cat = CATEGORIES.find(c=>c.id===e.item.cat);
      ctx.save();
      ctx.translate(p.x, p.y + Math.sin(e.wobble)*3);
      if (e.judged){
        ctx.globalAlpha = Math.max(0, 1 - (e.dist - TOTAL_LEN)/60);
      }
      // badan bug
      ctx.shadowColor = cat.color; ctx.shadowBlur = 12;
      const g = ctx.createRadialGradient(-4,-4,2,0,0,16);
      g.addColorStop(0, '#fff'); g.addColorStop(0.4, cat.color); g.addColorStop(1, '#1e293b');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(0,0,14,0,Math.PI*2); ctx.fill();
      ctx.shadowBlur = 0;
      // kaki
      ctx.strokeStyle = cat.color; ctx.lineWidth = 2;
      for (let k=-1;k<=1;k++){
        ctx.beginPath(); ctx.moveTo(k*6, 8); ctx.lineTo(k*10, 16); ctx.stroke();
      }
      // label
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 10px sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';
      ctx.fillText(e.item.text.length > 20 ? e.item.text.slice(0,19)+'…' : e.item.text, 0, -18);
      ctx.restore();
    }
  }

  function drawProjectiles(){
    for (const pr of projectiles){
      ctx.save();
      ctx.shadowColor = pr.color; ctx.shadowBlur = 12;
      ctx.fillStyle = pr.color;
      ctx.beginPath(); ctx.arc(pr.x, pr.y, 5, 0, Math.PI*2); ctx.fill();
      ctx.restore();
    }
  }

  function drawParticles(){
    for (const p of particles){
      ctx.globalAlpha = Math.max(0, p.life/0.6);
      ctx.fillStyle = p.color;
      ctx.beginPath(); ctx.arc(p.x, p.y, 3, 0, Math.PI*2); ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  function drawHUD(){
    // panel atas
    ctx.fillStyle = 'rgba(15,23,42,0.75)';
    roundRect(12, 12, 340, 74, 12); ctx.fill();
    ctx.fillStyle = '#7dd3fc';
    ctx.font = 'bold 13px sans-serif';
    ctx.textAlign = 'left'; ctx.textBaseline = 'top';
    ctx.fillText('🌸 Bunga Neon', 24, 22);
    ctx.fillStyle = '#e0f2fe';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('Bug dihalau: ' + correctCount + ' / ' + TARGET, 24, 42);
    // nyawa
    ctx.fillStyle = '#f87171';
    ctx.font = 'bold 14px sans-serif';
    let hearts = '';
    for (let i=0;i<lives;i++) hearts += '❤ ';
    ctx.fillText(hearts, 24, 64);

    // target kategori
    ctx.fillStyle = 'rgba(15,23,42,0.75)';
    roundRect(W-300, 12, 288, 74, 12); ctx.fill();
    ctx.fillStyle = '#7dd3fc';
    ctx.font = 'bold 12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('Menara tersedia:', W-288, 22);
    let tx = W-288;
    for (const c of CATEGORIES){
      ctx.fillStyle = c.color;
      roundRect(tx, 40, 88, 34, 8); ctx.fill();
      ctx.fillStyle = '#0f172a';
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(c.label, tx+44, 57);
      tx += 94;
    }

    // feedback
    if (feedback.timer > 0){
      ctx.globalAlpha = Math.min(1, feedback.timer);
      ctx.fillStyle = 'rgba(15,23,42,0.85)';
      roundRect(W/2-260, H-70, 520, 46, 10); ctx.fill();
      ctx.fillStyle = feedback.color;
      ctx.font = 'bold 14px sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(feedback.text.length > 70 ? feedback.text.slice(0,69)+'…' : feedback.text, W/2, H-47);
      ctx.globalAlpha = 1;
    }

    // watermark
    ctx.fillStyle = 'rgba(255,255,255,0.35)';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'right'; ctx.textBaseline = 'bottom';
    ctx.fillText('AISYS HTML5 Engine', W-14, H-8);
  }

  function drawTowerPicker(){
    if (selectedSlot < 0) return;
    const s = SLOTS[selectedSlot];
    const existing = towerAt(selectedSlot);
    const bw = 150, bh = 44;
    let bx = s.x - bw/2;
    let by = s.y + 30;
    if (by + bh > H - 10) by = s.y - bh - 30;
    if (bx < 10) bx = 10;
    if (bx + bw > W - 10) bx = W - bw - 10;

    ctx.fillStyle = 'rgba(15,23,42,0.95)';
    ctx.strokeStyle = '#7dd3fc'; ctx.lineWidth = 2;
    roundRect(bx, by, bw, bh, 10); ctx.fill(); ctx.stroke();

    if (existing){
      ctx.fillStyle = '#f87171';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('✕ Bongkar menara', bx+bw/2, by+bh/2);
    } else {
      const optW = (bw-16)/3;
      for (let i=0;i<CATEGORIES.length;i++){
        const c = CATEGORIES[i];
        const ox = bx + 8 + i*(optW+0);
        ctx.fillStyle = c.color;
        roundRect(ox, by+8, optW-4, bh-16, 6); ctx.fill();
        ctx.fillStyle = '#0f172a';
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(c.label.split(' ')[0], ox+(optW-4)/2, by+bh/2);
      }
    }
  }

  function drawStart(){
    drawBackground();
    ctx.fillStyle = 'rgba(10,15,30,0.75)';
    ctx.fillRect(0,0,W,H);
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = '#f472b6';
