    ctx.font = 'bold 18px sans-serif';
    ctx.fillText('▶ Ketuk untuk Main Lagi', W/2, 390);
    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    ctx.font = '12px sans-serif';
    ctx.fillText('Built with AISYS HTML5 Engine', W/2, H-40);
    ctx.fillText('STIKOM YOS SUDARSO', W/2, H-22);
  }

  function render(){
    ctx.setTransform(1,0,0,1,0,0);
    ctx.clearRect(0,0,cv.width,cv.height);
    ctx.setTransform(scale, 0, 0, scale, offX, offY);

    if (state === 'start'){ drawStart(); return; }
    if (state === 'win' || state === 'lose'){ drawEnd(); return; }

    drawBackground();
    drawPath();
    drawFlower();
    drawSlots();
    drawEnemies();
    drawProjectiles();
    drawParticles();
    drawTowerPicker();
    drawHUD();
  }

  // ---------- INPUT ----------
  function handleClick(lx, ly){
    unlockAudio();
    if (state === 'start'){ resetGame(); state = 'playing'; return; }
    if (state === 'win' || state === 'lose'){ resetGame(); state = 'playing'; return; }

    // cek picker dulu
    if (selectedSlot >= 0){
      const s = SLOTS[selectedSlot];
      const existing = towerAt(selectedSlot);
      const bw = 150, bh = 44;
      let bx = s.x - bw/2;
      let by = s.y + 30;
      if (by + bh > H - 10) by = s.y - bh - 30;
      if (bx < 10) bx = 10;
      if (bx + bw > W - 10) bx = W - bw - 10;
      if (lx >= bx && lx <= bx+bw && ly >= by && ly <= by+bh){
        if (existing){
          towers = towers.filter(t => t.slotIndex !== selectedSlot);
          sfx.place();
        } else {
          const optW = (bw-16)/3;
          for (let i=0;i<CATEGORIES.length;i++){
            const ox = bx + 8 + i*optW;
            if (lx >= ox && lx <= ox+optW-4){
              towers.push({ slotIndex: selectedSlot, cat: CATEGORIES[i].id, cool: 0 });
              sfx.place();
              break;
            }
          }
        }
        selectedSlot = -1;
        return;
      }
    }

    // cek slot
    for (let i=0;i<SLOTS.length;i++){
      const s = SLOTS[i];
      if (Math.hypot(lx-s.x, ly-s.y) < 24){
        selectedSlot = (selectedSlot === i) ? -1 : i;
        return;
      }
    }
    selectedSlot = -1;
  }

  cv.addEventListener('pointerdown', (e)=>{
    e.preventDefault();
    const p = toLogical(e.clientX, e.clientY);
    handleClick(p.x, p.y);
  });
  window.addEventListener('keydown', (e)=>{
    if (e.key === ' ' || e.key === 'Enter'){
      e.preventDefault();
      unlockAudio();
      if (state === 'start' || state === 'win' || state === 'lose'){ resetGame(); state = 'playing'; }
    }
  });

  // ---------- LOOP ----------
  function loop(ts){
    if (!lastTime) lastTime = ts;
    let dt = (ts - lastTime) / 1000;
    lastTime = ts;
    if (dt > 0.1) dt = 0.1;
    update(dt);
    render();
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
</script>
