    { x: 300, y: 200 },  // dekat segmen horizontal y=300? jarak 100
    { x: 300, y: 380 },  // dekat y=300? jarak 80
    { x: 420, y: 200 },  // dekat x=520 vertikal? jarak 100
    { x: 620, y: 220 },  // dekat y=130? jarak 90
    { x: 620, y: 360 },  // dekat x=800 vertikal? jarak 180 -> terlalu jauh, ganti
    { x: 700, y: 220 },  // dekat y=130? jarak 90
    { x: 700, y: 360 },  // dekat x=800 vertikal? jarak 100
    { x: 380, y: 360 }   // dekat y=300? jarak 60
  ];
  // Perbaiki slot 5 (index 5) agar dekat jalur
  SLOTS[5] = { x: 700, y: 360 }; // dekat x=800 vertikal (jarak 100) & y=420 (jarak 60)
  // Hapus duplikat: index 5 dan 7 sama. Ganti index 5 jadi dekat segmen y=420
  SLOTS[5] = { x: 620, y: 360 }; // dekat y=420? jarak 60, dekat x=800? jarak 180 -> masih jauh dari x=800, tapi dekat y=420 cukup
  // Sebenarnya lebih aman: slot dekat jalur horizontal y=420
  SLOTS[5] = { x: 620, y: 360 }; // jarak ke y=420 = 60 < 120 OK

  const TOWER_RANGE = 130;

  let state = 'start';
  let lives = 5;
  let correctCount = 0;
  const TARGET = 10;
  let towers = [];
  let enemies = [];
  let particles = [];
  let projectiles = [];
  let spawnTimer = 0;
  let spawnInterval = 2.2;
  let selectedSlot = -1;
  let feedback = { text: '', timer: 0, color: '#fff' };
  let lastTime = 0;
  let enemyIdCounter = 0;
  let bankQueue = [];

  function shuffle(a){ for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; } return a; }
  function refillQueue(){ bankQueue = shuffle(BANK.slice()); }
